#include "wsoundbeltfeed89.h"
static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}static wsound89_i16 nz(wsoundbeltfeed89_context*c){c->state=c->state*1664525U+1013904223U;return(wsound89_i16)((c->state>>16)&65535U);}
wsound89_result wsoundbeltfeed89_init(wsoundbeltfeed89_context*c,wsound89_u32 rate,wsound89_u32 seed){if(!c||!rate)return WSOUND89_EINVAL;c->rate=rate;c->phase=c->step=0;c->state=seed?seed:0x42454C54U;c->env=c->pulse=c->res=0;c->tension_q15=c->metal_q15=0;c->active=c->gate=c->stage=0;return WSOUND89_OK;}
wsound89_result wsoundbeltfeed89_start(wsoundbeltfeed89_context*c,wsound89_u16 rpm,wsound89_u16 tension,wsound89_u16 metal){if(!c||!rpm)return WSOUND89_EINVAL;c->step=(4294967295U/(60U*c->rate))*(wsound89_u32)rpm;if(!c->step)c->step=1;c->tension_q15=tension;c->metal_q15=metal;c->env=28000;c->active=c->gate=1;return WSOUND89_OK;}void wsoundbeltfeed89_set_gate(wsoundbeltfeed89_context*c,int g){if(c)c->gate=(wsound89_u8)(g?1:0);}
wsound89_i16 wsoundbeltfeed89_process_sample(wsoundbeltfeed89_context*c){wsound89_u32 old;wsound89_i32 n,mix;if(!c||!c->active)return 0;old=c->phase;c->phase+=c->step;if(c->phase<old){c->stage=6;c->pulse=((wsound89_i32)nz(c)*(10000+(c->tension_q15>>1)))>>15;}if(c->stage){n=nz(c);c->pulse=(c->pulse*23000)>>15;c->pulse+=((wsound89_i32)n*(c->metal_q15>>3))>>15;c->stage--;}else c->pulse=(c->pulse*15000)>>15;c->res+=(c->pulse-c->res)>>3;mix=c->pulse+(c->res>>1);mix=(mix*c->env)>>15;if(c->gate)c->env+=(29000-c->env)>>8;else c->env-=(c->env>>7)+10;if(c->env<20){c->active=0;c->env=0;}return sat(mix);}
